package com.anitec.backend;

import org.flywaydb.core.Flyway;
import org.junit.jupiter.api.Test;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
import org.testcontainers.containers.PostgreSQLContainer;
import org.testcontainers.junit.jupiter.*;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

@Testcontainers
class PasswordRecoveryMigrationTests {
 @Container static PostgreSQLContainer<?> postgres=new PostgreSQLContainer<>("postgres:16-alpine");
 DriverManagerDataSource database(){String name="recovery_"+UUID.randomUUID().toString().replace("-","");new JdbcTemplate(new DriverManagerDataSource(postgres.getJdbcUrl(),postgres.getUsername(),postgres.getPassword())).execute("CREATE DATABASE "+name);return new DriverManagerDataSource("jdbc:postgresql://"+postgres.getHost()+":"+postgres.getMappedPort(5432)+"/"+name,postgres.getUsername(),postgres.getPassword());}
 Flyway flyway(DriverManagerDataSource db,String version){return Flyway.configure().dataSource(db).target(version).placeholders(Map.of("admin_email","retired@bootstrap.invalid","admin_password_hash","DISABLED-HISTORICAL-BOOTSTRAP","demo_seed","false")).load();}
 UUID account(JdbcTemplate j){return j.queryForObject("INSERT INTO identity_accounts(email,password_hash,name,last_name,role,status,verified_at) VALUES (?,'synthetic-hash','Test','Recovery','GANADERO','ACTIVA',now()) RETURNING id",UUID.class,UUID.randomUUID()+"@example.invalid");}
 void recovery(JdbcTemplate j,UUID id,UUID emission){j.update("INSERT INTO identity_password_recovery(account_id,purpose,window_started_at,emission_count,last_issued_at,emission_id,code_verifier,expires_at,failed_attempts) VALUES (?,'PASSWORD_RECOVERY',now(),1,now(),?,?,now()+interval '10 minutes',0)",id,emission,new byte[32]);}
 @Test void freshInstallationAndRepeatFlyway(){var db=database();assertThat(flyway(db,"latest").migrate().migrationsExecuted).isEqualTo(16);var j=new JdbcTemplate(db);assertThat(j.queryForObject("SELECT count(*) FROM identity_password_recovery",Integer.class)).isZero();assertThat(j.queryForObject("SELECT count(*) FROM identity_accounts",Integer.class)).isZero();assertThat(flyway(db,"latest").migrate().migrationsExecuted).isZero();}
 @Test void upgradeFromV15PreservesAccountsSessionsTokensAndBusinessData(){var db=database();flyway(db,"15").migrate();var j=new JdbcTemplate(db);UUID id=account(j),session=UUID.randomUUID();j.update("INSERT INTO identity_sessions(id,account_id,created_at,expires_at) VALUES (?,?,now(),now()+interval '168 hours')",session,id);j.update("INSERT INTO identity_session_tokens(token_digest,session_id,created_at,expires_at) VALUES (?,?,now(),now()+interval '1 day')","a".repeat(64),session);UUID farm=j.queryForObject("INSERT INTO livestock_farms(farmer_id,name) VALUES (?,'Preserved farm') RETURNING id",UUID.class,id);var a=j.queryForMap("SELECT * FROM identity_accounts WHERE id=?",id);var s=j.queryForMap("SELECT * FROM identity_sessions WHERE id=?",session);var t=j.queryForMap("SELECT * FROM identity_session_tokens WHERE session_id=?",session);assertThat(flyway(db,"latest").migrate().migrationsExecuted).isEqualTo(1);assertThat(j.queryForMap("SELECT * FROM identity_accounts WHERE id=?",id).equals(a)).isTrue();assertThat(j.queryForMap("SELECT * FROM identity_sessions WHERE id=?",session).equals(s)).isTrue();assertThat(j.queryForMap("SELECT * FROM identity_session_tokens WHERE session_id=?",session).equals(t)).isTrue();assertThat(j.queryForObject("SELECT count(*) FROM livestock_farms WHERE id=?",Integer.class,farm)).isEqualTo(1);assertThat(j.queryForObject("SELECT count(*) FROM identity_password_recovery",Integer.class)).isZero();}
 @Test void invalidCountersPurposeVerifierAndTimestampsAreRejectedWithoutChangingValidRow(){var db=database();flyway(db,"latest").migrate();var j=new JdbcTemplate(db);UUID id=account(j);recovery(j,id,UUID.randomUUID());for(String assignment:List.of("emission_count=0","emission_count=6","failed_attempts=6","failed_attempts=5","purpose='EMAIL_VERIFICATION'","code_verifier=decode('00','hex')","expires_at=last_issued_at+interval '11 minutes'","last_issued_at=window_started_at+interval '25 hours'")){assertThatThrownBy(()->j.update("UPDATE identity_password_recovery SET "+assignment+" WHERE account_id=?",id)).isInstanceOf(org.springframework.dao.DataIntegrityViolationException.class);}assertThat(j.queryForObject("SELECT emission_count FROM identity_password_recovery WHERE account_id=?",Integer.class,id)).isEqualTo(1);assertThat(j.queryForObject("SELECT failed_attempts FROM identity_password_recovery WHERE account_id=?",Integer.class,id)).isZero();}
 @Test void accountAndIssuanceConstraintsPreventReassignment(){var db=database();flyway(db,"latest").migrate();var j=new JdbcTemplate(db);UUID a=account(j),b=account(j),emission=UUID.randomUUID();recovery(j,a,emission);assertThatThrownBy(()->recovery(j,b,emission)).isInstanceOf(org.springframework.dao.DataIntegrityViolationException.class);assertThatThrownBy(()->recovery(j,UUID.randomUUID(),UUID.randomUUID())).isInstanceOf(org.springframework.dao.DataIntegrityViolationException.class);assertThat(j.queryForObject("SELECT count(*) FROM identity_password_recovery",Integer.class)).isEqualTo(1);}
 @Test void conflictingPreexistingStructureFailsWithoutAutomaticDestruction(){var db=database();flyway(db,"15").migrate();var j=new JdbcTemplate(db);UUID id=account(j);j.execute("CREATE TABLE identity_password_recovery(marker TEXT)");j.update("INSERT INTO identity_password_recovery VALUES ('preserve-marker')");assertThatThrownBy(()->flyway(db,"latest").migrate()).isInstanceOf(org.flywaydb.core.api.FlywayException.class);assertThat(j.queryForObject("SELECT marker FROM identity_password_recovery",String.class)).isEqualTo("preserve-marker");assertThat(j.queryForObject("SELECT count(*) FROM identity_accounts WHERE id=?",Integer.class,id)).isEqualTo(1);assertThat(j.queryForObject("SELECT count(*) FROM flyway_schema_history WHERE version='16' AND success",Integer.class)).isZero();}
}
